    /// <summary>Proves the UQ0.16 text seam at every swept raw: the renderer reproduces the oracle's exact decimal
    /// expansion, the span formatter writes exactly that and REFUSES every destination one character short with nothing
    /// reported written, all four parse entry points read the exact rendering back to the raw it came from, and two
    /// derived texts that do not land on the grid — the rendering truncated, and the rendering with a digit appended —
    /// reach the same accept-or-refuse decision and the same raw as the shared-nothing text oracle.</summary>
    /// <param name="left">The first sampled operand lane.</param>
    /// <param name="right">The second sampled operand lane.</param>
    /// <returns>The counterexample text, or <see langword="null"/> when the claim holds.</returns>
    public static string? UnitFraction16TextMatchesOracle(long[] left, long[] right) {
        const int bits = UnitFraction16.FractionBitCount;

        var raw = UnitFraction16Raw(raw: left[0]);
        var value = UnitFraction16.FromRawBits(value: raw);
        var reference = Oracles.ExactDyadicDecimal(numerator: new BigInteger(value: raw), shift: bits);
        Span<char> buffer = stackalloc char[(UnitFraction16.TotalBitCount + 4)];

        if (value.ToString() != reference) { return $"raw {raw} rendered as '{value.ToString()}', expected '{reference}'"; }

        if (!value.TryFormat(destination: buffer[..reference.Length], charsWritten: out var written, format: default, provider: null) ||
            (written != reference.Length) ||
            (new string(value: buffer[..written]) != reference)) { return $"the span format of raw {raw} did not write '{reference}'"; }

        if (!value.TryFormat(destination: buffer, charsWritten: out var spare, format: default, provider: null) || (spare != reference.Length)) { return $"the span format of raw {raw} into a longer destination reported {spare}"; }

        for (var length = 0; (length < reference.Length); ++length) {
            if (value.TryFormat(destination: buffer[..length], charsWritten: out var refused, format: default, provider: null) || (0 != refused)) { return $"the span format of raw {raw} accepted a destination of {length} characters"; }
        }

        if (UnitFraction16.Parse(s: reference, provider: null) != value) { return $"the string parse of '{reference}' did not return raw {raw}"; }
        if (UnitFraction16.Parse(s: reference.AsSpan(), provider: null) != value) { return $"the span parse of '{reference}' did not return raw {raw}"; }
        if (!UnitFraction16.TryParse(s: reference, provider: null, result: out var parsed) || (parsed != value)) { return $"the string try-parse of '{reference}' did not return raw {raw}"; }
        if (!UnitFraction16.TryParse(s: reference.AsSpan(), provider: null, result: out var spanParsed) || (spanParsed != value)) { return $"the span try-parse of '{reference}' did not return raw {raw}"; }

        foreach (var text in UnitFractionDerivedTexts(rendering: reference, raw: raw)) {
            var accepted = UnitFraction16.TryParse(s: text, provider: null, result: out var actual);
            var admitted = Oracles.TryUnitFractionText(text: text, fractionBitCount: bits, raw: out var expected);

            if (accepted != admitted) { return $"'{text}' was {(accepted ? "accepted" : "refused")} by the subject and {(admitted ? "accepted" : "refused")} by the oracle"; }
            if (accepted && (actual.Value != expected)) { return $"'{text}' parsed to raw {actual.Value}, expected {expected}"; }
            if (!accepted && (actual != default)) { return $"the refusal of '{text}' left raw {actual.Value} behind"; }
        }

        return null;
    }

