    /// <summary>Proves the UQ0.16 text contract on its own committed ladder: every accepted spelling reaches the
    /// hand-derived raw AND the oracle's, through both parse routes; every refused spelling is refused by both, leaves the
    /// default behind, and makes the throwing route throw; the null string is a refusal on one route and an
    /// ArgumentNullException on the other; and the provider is honoured, so a comma-separator culture moves the decimal
    /// point and the invariant spelling stops parsing under it.</summary>
    /// <returns>The counterexample text, or <see langword="null"/> when the claim holds.</returns>
    public static string? UnitFraction16ParseLadderHolds() {
        const int bits = UnitFraction16.FractionBitCount;

        foreach (var (text, expected) in UnitFraction16ParseLadder) {
            if (!UnitFraction16.TryParse(s: text, provider: null, result: out var parsed) || (parsed.Value != expected)) { return $"'{text}' parsed to raw {parsed.Value}, expected {expected}"; }
            if (UnitFraction16.Parse(s: text, provider: null).Value != expected) { return $"the throwing string parse of '{text}' is wrong"; }
            if (UnitFraction16.Parse(s: text.AsSpan(), provider: null).Value != expected) { return $"the throwing span parse of '{text}' is wrong"; }
            if (!Oracles.TryUnitFractionText(text: text, fractionBitCount: bits, raw: out var admitted) || (admitted != expected)) { return $"the oracle reads '{text}' as raw {admitted}, expected {expected}"; }
        }

        foreach (var text in UnitFraction16RefusedTexts) {
            if (UnitFraction16.TryParse(s: text, provider: null, result: out var refused) || (refused != default)) { return $"'{text}' was accepted, or left raw {refused.Value} behind"; }
            if (Oracles.TryUnitFractionText(text: text, fractionBitCount: bits, raw: out _)) { return $"the oracle accepted '{text}'"; }

            try {
                _ = UnitFraction16.Parse(s: text, provider: null);

                return $"the throwing string parse accepted '{text}'";
            } catch (FormatException) { }

            try {
                _ = UnitFraction16.Parse(s: text.AsSpan(), provider: null);

                return $"the throwing span parse accepted '{text}'";
            } catch (FormatException) { }
        }

        if (UnitFraction16.TryParse(s: ((string?)null), provider: null, result: out var fromNull) || (fromNull != default)) { return "a null string was accepted"; }

        try {
            _ = UnitFraction16.Parse(s: ((string)null!), provider: null);

            return "the throwing parse accepted a null string";
        } catch (ArgumentNullException exception) {
            if (exception.ParamName != "s") { return $"the null refusal named '{exception.ParamName}'"; }
        }

        // The provider is honoured on both routes: a comma-separator culture moves the point, and the invariant spelling
        // stops naming a number under it.
        var comma = new NumberFormatInfo { NumberDecimalSeparator = ",", NumberGroupSeparator = ".", };

        if (UnitFraction16.Parse(s: "0,5", provider: comma).Value != 32768) { return "the comma spelling did not parse under a comma-separator provider"; }
        if (UnitFraction16.TryParse(s: "0.5", provider: comma, result: out _)) { return "the point spelling parsed under a comma-separator provider"; }
        if (UnitFraction16.Parse(s: "0.5", provider: null).Value != 32768) { return "a null provider is not the invariant culture"; }

        return null;
    }

